<div class="content-heading mb-4"><h1>POS Drafts</h1><p>Held carts can be continued and completed whenever the customer is ready.</p></div>
<div class="panel p-0 overflow-hidden"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Draft reference</th><th>Saved</th><th>Customer</th><th>Warehouse</th><th>Items</th><th class="text-end">Total</th><th class="text-end">Action</th></tr></thead><tbody><?php $__empty_1 = true; $__currentLoopData = $orders; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $order): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); $__empty_1 = false; ?><tr><td class="fw-bold"><?php echo e($order->order_number); ?></td><td><?php echo e($order->created_at->format('d M Y, h:i A')); ?></td><td><?php echo e($order->customer_name ?: 'Walk-in customer'); ?><?php if($order->customer_phone): ?><br><small class="text-muted"><?php echo e($order->customer_phone); ?></small><?php endif; ?></td><td><?php echo e($order->warehouse?->name ?: '—'); ?></td><td><?php echo e($order->items->sum('quantity')); ?></td><td class="text-end fw-bold">$<?php echo e(number_format($order->total,2)); ?></td><td class="text-end"><a class="btn btn-sm text-white" style="background:var(--brand)" href="<?php echo e(route('admin.pos.drafts.continue',$order)); ?>"><i class="bi bi-play-fill me-1"></i>Continue</a></td></tr><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); if ($__empty_1): ?><tr><td colspan="7" class="text-center py-5 text-muted"><i class="bi bi-pause-circle fs-3 d-block mb-2"></i>There are no held POS carts.</td></tr><?php endif; ?></tbody></table></div></div><div class="mt-3"><?php echo e($orders->links()); ?></div>
